PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS studies (id TEXT PRIMARY KEY, config_json TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS invitations (code_hash TEXT PRIMARY KEY, label TEXT NOT NULL DEFAULT '', mode TEXT NOT NULL CHECK(mode IN ('test','live')), created_at TEXT NOT NULL, session_id TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, invitation_hash TEXT NOT NULL UNIQUE, mode TEXT NOT NULL, phase TEXT NOT NULL DEFAULT 'intro', revision INTEGER NOT NULL DEFAULT 0, last_action TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, assigned_at TEXT, condition TEXT, disclosure TEXT, case_id TEXT NOT NULL, protocol_version TEXT NOT NULL, stimulus_hash TEXT NOT NULL, initial_text TEXT, draft_text TEXT, draft_seq INTEGER NOT NULL DEFAULT 0, submitted_text TEXT, submitted_at TEXT, completed_at TEXT, completion_code TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, question_order TEXT NOT NULL, consent_json TEXT NOT NULL, meta_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS responses (session_id TEXT NOT NULL REFERENCES sessions(id), phase TEXT NOT NULL, action_id TEXT NOT NULL UNIQUE, value_json TEXT NOT NULL, received_at TEXT NOT NULL, PRIMARY KEY(session_id,phase));
CREATE TABLE IF NOT EXISTS actions (session_id TEXT NOT NULL REFERENCES sessions(id), action_id TEXT NOT NULL, from_phase TEXT NOT NULL, to_phase TEXT NOT NULL, revision INTEGER NOT NULL, received_at TEXT NOT NULL, PRIMARY KEY(session_id,action_id));
CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id TEXT NOT NULL REFERENCES sessions(id), event_id TEXT NOT NULL, page_id TEXT NOT NULL, seq INTEGER NOT NULL, phase TEXT NOT NULL, type TEXT NOT NULL, client_wall TEXT NOT NULL, client_mono REAL NOT NULL, received_at TEXT NOT NULL, payload_json TEXT NOT NULL, UNIQUE(session_id,event_id), UNIQUE(session_id,page_id,seq));
CREATE INDEX IF NOT EXISTS events_session ON events(session_id,id);
CREATE TABLE IF NOT EXISTS versions (version TEXT PRIMARY KEY, stimulus_hash TEXT NOT NULL, snapshot_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS campaigns (token_hash TEXT PRIMARY KEY, label TEXT NOT NULL DEFAULT '', mode TEXT NOT NULL CHECK(mode IN ('test','live')), keyword TEXT NOT NULL DEFAULT '', capacity INTEGER NOT NULL DEFAULT 0, completion_target INTEGER NOT NULL DEFAULT 0, open INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS session_cases (session_id TEXT NOT NULL REFERENCES sessions(id), idx INTEGER NOT NULL, case_id TEXT NOT NULL, base_id TEXT NOT NULL, condition TEXT NOT NULL, sender TEXT NOT NULL, initial_text TEXT NOT NULL, draft_text TEXT NOT NULL, draft_seq INTEGER NOT NULL DEFAULT 0, submitted_text TEXT, submitted_at TEXT, version_hash TEXT, PRIMARY KEY(session_id,idx));
